#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
const PATCH = "MVP Trainer V5 R9.3.3 Training Intelligence Build Fix";
const FILES = [{"target":"src/lib/trainingIntelligence.ts","sha256":"fd8f7cca8fde2d666f6535766b1fc0feb6d44477d62c9f21b78b1fc7c92dc55e","base64":""},{"target":"src/features/coach/CoachPage.tsx","sha256":"c9bd45007d3e1378756a438c357a7608c71a1b759365282e868b06a06530c728","base64":""},{"target":"src/features/workout/WorkoutPlayerPage.tsx","sha256":"a9a5f61239a0781c99198927dc17877740af060af653387361f33fcc279e65c5","base64":""},{"target":"src/features/workout/TodayPage.tsx","sha256":"3971aaeae7f9176a9618873b33e3321eddfde808f74175bbee185eb7d9f4088f","base64":""},{"target":"src/features/progress/ProgressPage.tsx","sha256":"be989602f741e8bb998ab99795bb5cb12bfcf353b361cdbade74b9fc63a19130","base64":""}];
function sha256(buffer) { return crypto.createHash("sha256").update(buffer).digest("hex"); }
function findRepo(start) { let current=path.resolve(start); for(let i=0;i<8;i+=1){ if(fs.existsSync(path.join(current,"package.json"))&&fs.existsSync(path.join(current,"src"))) return current; const parent=path.dirname(current); if(parent===current) break; current=parent; } return null; }
const repo=findRepo(process.cwd());
if(!repo){ console.error("ERROR: Could not find the MVP Trainer repo. Run this installer from the repo root or a folder inside it."); process.exit(1); }
function walkFiles(root, matcher, depth=0){
  if(depth>8 || !fs.existsSync(root)) return [];
  const out=[];
  for(const dirent of fs.readdirSync(root,{withFileTypes:true})){
    const full=path.join(root,dirent.name);
    if(dirent.isDirectory()){
      if(["node_modules","dist","build",".git",".mvp-backups"].includes(dirent.name)) continue;
      out.push(...walkFiles(full,matcher,depth+1));
    } else if(matcher(full)) out.push(full);
  }
  return out;
}
function resolveExistingSource(preferredRel, markers=[]){
  const preferred=path.join(repo,preferredRel);
  if(fs.existsSync(preferred)) return preferredRel;
  const base=path.basename(preferredRel);
  const candidates=walkFiles(path.join(repo,"src","features"),(full)=>path.basename(full)===base);
  const scored=candidates.map((full)=>{
    let text=""; try{text=fs.readFileSync(full,"utf8")}catch{}
    const score=markers.reduce((sum,marker)=>sum+(text.includes(marker)?1:0),0);
    return {full,score};
  }).sort((a,b)=>b.score-a.score);
  if(scored.length && scored[0].score===markers.length) return path.relative(repo,scored[0].full).replace(/\\/g,"/");
  return null;
}
const resolvedToday = resolveExistingSource("src/features/workout/TodayPage.tsx", ["export function TodayPage", "UPCOMING TRAINING", "Coming Up"]);
if(resolvedToday && resolvedToday !== "src/features/workout/TodayPage.tsx"){
  const entry=FILES.find((item)=>item.target==="src/features/workout/TodayPage.tsx");
  if(entry) entry.target=resolvedToday;
}
console.log(`\n${PATCH}`); console.log(`Repo: ${repo}\n`);
if(resolvedToday && resolvedToday !== "src/features/workout/TodayPage.tsx") console.log(`Detected Training page: ${resolvedToday}`);
const requiredExisting=[
  {preferred:"src/features/coach/CoachPage.tsx",markers:["export function CoachPage","Today's Coaching Brief"]},
  {preferred:"src/features/workout/WorkoutPlayerPage.tsx",markers:["ProgressionGuidance","sameCanonicalExercise"]},
  {preferred:resolvedToday || "src/features/workout/TodayPage.tsx",markers:[]},
  {preferred:"src/features/progress/ProgressPage.tsx",markers:["export function ProgressPage","BODY & NUTRITION"]},
];
for(const item of requiredExisting){
  const rel=item.markers.length ? (resolveExistingSource(item.preferred,item.markers) || item.preferred) : item.preferred;
  if(!fs.existsSync(path.join(repo,rel))){
    console.error(`ERROR: Expected current source file is missing: ${item.preferred}`);
    if(item.preferred.includes("TodayPage.tsx")) console.error("The installer also searched src/features recursively for the Training page but could not identify it.");
    console.error("No files were changed."); process.exit(1);
  }
}
const changes=FILES.filter((entry)=>{ const target=path.join(repo,entry.target); return !fs.existsSync(target)||sha256(fs.readFileSync(target))!==entry.sha256; });
if(!changes.length){ console.log("Already installed. All R9.3.3 files match the expected hashes."); process.exit(0); }
const stamp=new Date().toISOString().replace(/[:.]/g,"-");
const backupRoot=path.join(repo,".mvp-backups",`r9-3-3-training-intelligence-${stamp}`); fs.mkdirSync(backupRoot,{recursive:true});
for(const entry of changes){ const target=path.join(repo,entry.target); if(fs.existsSync(target)){ const backup=path.join(backupRoot,entry.target); fs.mkdirSync(path.dirname(backup),{recursive:true}); fs.copyFileSync(target,backup); } }
for(const entry of FILES){ const target=path.join(repo,entry.target); const contents=Buffer.from(entry.base64,"base64"); fs.mkdirSync(path.dirname(target),{recursive:true}); fs.writeFileSync(target,contents); const actual=sha256(fs.readFileSync(target)); if(actual!==entry.sha256){ console.error(`ERROR: Verification failed after writing ${entry.target}`); process.exit(1); } console.log(`OK  ${entry.target}`); }
console.log(`\nBackup: ${path.relative(repo,backupRoot)}`); console.log("Install complete."); console.log("Next: run npm run build from the repo root.\n");
